//! Explicit fresh-seed CUDA draws through the actual managed tensor executor.
//! Repeatability here is scoped to one device/runtime/provider and fixed shape.
//! No deployed Torch oracle, distribution-quality or cross-device parity has
//! been established; changing launch geometry may change the generated bytes.
use super::*;
use ferrum_diffusion::{pack_spatial_into, unpack_spatial_into, SingleFrameLatentShape};
use ferrum_kernels::backend::cuda::vnext_ops::{
    cuda_vnext_philox_normal_bf16_provider, CudaPhiloxDeviceGeometry,
    CUDA_PHILOX_NORMAL_BF16_NUMERICAL_PROFILE_ID,
};
use ferrum_models::normal_noise::{NormalNoiseConfig, NormalNoiseFamily};
use sha2::{Digest, Sha256};

const SEED: u64 = 0x0123_4567_89ab_cdef;
const OTHER_SEED: u64 = SEED ^ (1_u64 << 40);

fn prepared(config: &NormalNoiseConfig) -> PreparedModelFamily {
    TypedFamilyRegistration::new(
        NormalNoiseFamily::new(CUDA_PHILOX_NORMAL_BF16_NUMERICAL_PROFILE_ID).unwrap(),
    )
    .prepare_with_profile(
        &serde_json::to_value(config).unwrap(),
        &NumericalProfileId::new(CUDA_PHILOX_NORMAL_BF16_NUMERICAL_PROFILE_ID).unwrap(),
    )
    .unwrap()
}

#[test]
fn philox_fixture_prepares_real_family_state_ports_and_capability_without_context() {
    let config = NormalNoiseConfig::new(3, 1, 257).unwrap();
    let family = prepared(&config);
    assert!(matches!(family.weights(), ModelWeights::None));
    assert!(family.program().weights().is_empty());
    assert_eq!(
        family.program().inputs(),
        [id::<ProgramValueId>(NormalNoiseFamily::STATE_ID)]
    );
    assert_eq!(
        family.program().outputs(),
        [id::<ProgramValueId>(NormalNoiseFamily::OUTPUT_ID)]
    );
    assert_eq!(family.program().blocks()[0].nodes.len(), 1);
    let node = &family.program().blocks()[0].nodes[0];
    assert_eq!(node.operation_id.as_str(), PHILOX_NORMAL_BF16_OPERATION_ID);
    assert_eq!(node.work, ProgramNodeWorkSpec::Fixed);
    assert!(node.attributes.is_empty());
    assert_eq!(
        family.numerical_profile().id.as_str(),
        CUDA_PHILOX_NORMAL_BF16_NUMERICAL_PROFILE_ID
    );
    let options = config.compile_options().unwrap();
    let state: ProgramValueId = id(NormalNoiseFamily::STATE_ID);
    let output: ProgramValueId = id(NormalNoiseFamily::OUTPUT_ID);
    assert_eq!(
        options.tensor_specs()[&state],
        family.program().input_tensor_specs()[&state]
    );
    assert_eq!(options.tensor_specs()[&state].dimensions, [4]);
    assert_eq!(
        options.tensor_specs()[&state].element_type,
        ElementType::U32
    );
    assert_eq!(options.tensor_specs()[&output].dimensions, [1, 3, 1, 257]);
    assert_eq!(
        options.tensor_specs()[&output].element_type,
        ElementType::Bf16
    );
    let shape = PhiloxNormalBf16Geometry::new(
        &NormalNoiseConfig::state_tensor().unwrap(),
        &config.output_tensor().unwrap(),
    )
    .unwrap();
    assert_eq!((shape.element_count(), shape.output_bytes()), (771, 1542));
    let device = cuda_tensor_runtime_config(0, id("device.cuda.philox.metadata")).unwrap();
    assert!(device
        .capabilities
        .contains(&id::<CapabilityId>(PHILOX_NORMAL_BF16_CAPABILITY_ID)));
    let registration = TypedFamilyRegistration::new(
        NormalNoiseFamily::new(CUDA_PHILOX_NORMAL_BF16_NUMERICAL_PROFILE_ID).unwrap(),
    );
    for invalid in [
        serde_json::json!({"channels":0,"height":1,"width":257}),
        serde_json::json!({"channels":3,"height":1,"width":257,"batch":2}),
    ] {
        assert!(registration
            .prepare_with_profile(
                &invalid,
                &NumericalProfileId::new(CUDA_PHILOX_NORMAL_BF16_NUMERICAL_PROFILE_ID).unwrap()
            )
            .is_err());
    }
    // The same element count is not permission to bind a packed or wrong-dtype
    // output directly to the NCHW operator.
    for wrong in [
        input_spec(vec![1, 257, 3], ElementType::Bf16),
        input_spec(vec![1, 3, 1, 257], ElementType::F16),
    ] {
        assert!(
            PhiloxNormalBf16Geometry::new(&NormalNoiseConfig::state_tensor().unwrap(), &wrong)
                .is_err()
        );
    }
}

#[test]
fn fresh_seed_serialization_and_unpatched_mapping_have_literal_expectations() {
    let state = PhiloxSeedOffset::fresh(SEED);
    assert_eq!(state.words(), [0x89ab_cdef, 0x0123_4567, 0, 0]);
    assert_eq!(
        state.little_endian_bytes(),
        [0xef, 0xcd, 0xab, 0x89, 0x67, 0x45, 0x23, 0x01, 0, 0, 0, 0, 0, 0, 0, 0]
    );
    assert_eq!(
        PhiloxSeedOffset::fresh(OTHER_SEED).words()[0],
        state.words()[0]
    );
    assert_ne!(
        PhiloxSeedOffset::fresh(OTHER_SEED).words()[1],
        state.words()[1]
    );
    let shape = SingleFrameLatentShape::new(1, 3, 1, 2).unwrap();
    let nchw = [0x3f80_u16, 0x4000, 0x4040, 0x4080, 0x40a0, 0x40c0];
    let mut packed = [0_u16; 6];
    pack_spatial_into(shape, &nchw, &mut packed).unwrap();
    assert_eq!(packed, [0x3f80, 0x4040, 0x40a0, 0x4000, 0x4080, 0x40c0]);
    let mut restored = [0_u16; 6];
    unpack_spatial_into(shape, &packed, &mut restored).unwrap();
    assert_eq!(restored, nchw);
}

fn state_input(host: &HostMemoryAccount, seed: u64) -> ManagedHostTensor {
    let mut storage = host
        .allocate_zeroed(HostMemoryClass::InputPreprocess, 16)
        .unwrap();
    storage
        .as_mut()
        .copy_from_slice(&PhiloxSeedOffset::fresh(seed).little_endian_bytes());
    ManagedHostTensor::new(
        id(NormalNoiseFamily::STATE_ID),
        NormalNoiseConfig::state_tensor().unwrap(),
        storage.freeze(),
    )
    .unwrap()
}

fn finite(bytes: &[u8]) {
    assert!(!bytes.is_empty() && bytes.len() % 2 == 0);
    for (index, pair) in bytes.chunks_exact(2).enumerate() {
        let bits = u16::from_le_bytes([pair[0], pair[1]]);
        assert!(
            half::bf16::from_bits(bits).is_finite(),
            "nonfinite generated element {index}"
        );
    }
}

fn managed_layout_check(host: &HostMemoryAccount, shape: [u64; 4], nchw: &ManagedHostBytes) {
    let [b, c, h, w] = shape.map(|v| usize::try_from(v).unwrap());
    let layout = SingleFrameLatentShape::new(b, c, h, w).unwrap();
    let mut packed = host
        .allocate_zeroed(HostMemoryClass::InputPreprocess, nchw.len())
        .unwrap();
    pack_spatial_into(
        layout,
        bytemuck::cast_slice::<u8, [u8; 2]>(nchw.bytes()),
        bytemuck::cast_slice_mut::<u8, [u8; 2]>(packed.as_mut()),
    )
    .unwrap();
    let packed = packed.freeze();
    assert!(host.owns(&packed));
    let positions = h * w;
    for position in 0..positions {
        for channel in 0..c {
            let source = (channel * positions + position) * 2;
            let destination = (position * c + channel) * 2;
            assert_eq!(
                &packed.bytes()[destination..destination + 2],
                &nchw.bytes()[source..source + 2]
            );
        }
    }
    let mut restored = host
        .allocate_zeroed(HostMemoryClass::InputPreprocess, nchw.len())
        .unwrap();
    unpack_spatial_into(
        layout,
        bytemuck::cast_slice::<u8, [u8; 2]>(packed.bytes()),
        bytemuck::cast_slice_mut::<u8, [u8; 2]>(restored.as_mut()),
    )
    .unwrap();
    assert_eq!(restored.freeze().bytes(), nchw.bytes());
    drop(packed);
}

fn exercise_shape(
    runtime: &Arc<CudaDeviceRuntime>,
    registry: &OperationRuntimeRegistry<CudaDeviceRuntime>,
    catalog: &CapabilityCatalog,
    config: NormalNoiseConfig,
    label: &str,
) -> (HostMemoryAccount, ManagedHostBytes) {
    let family = prepared(&config);
    let output_spec = config.output_tensor().unwrap();
    let geometry =
        PhiloxNormalBf16Geometry::new(&NormalNoiseConfig::state_tensor().unwrap(), &output_spec)
            .unwrap();
    let output_bytes = usize::try_from(geometry.output_bytes()).unwrap();
    // Two result owners can coexist for repeatability checks; two charged
    // input-class buffers support the exact pack/unpack roundtrip separately.
    let host = HostMemoryAccount::new(
        HostMemoryLimits::new(
            4 * output_bytes + 16,
            HostMemoryClassLimits {
                input_preprocess_bytes: 2 * output_bytes + 16,
                output_bytes: 2 * output_bytes,
                transfer_staging_bytes: 0,
                weight_backing_bytes: 0,
            },
        )
        .unwrap(),
    );
    let compiled = ProgramPlanCompiler::compile(
        &family,
        catalog,
        &policy(runtime.as_ref()),
        &registry.planning(),
        &config.compile_options().unwrap(),
    )
    .unwrap();
    let executable = compiled.executable();
    let plan = executable.execution_plan();
    assert!(matches!(
        plan.payload().execution_weights(),
        ExecutionWeights::None
    ));
    assert!(plan.payload().memory().static_allocations().is_empty());
    let node = &plan.payload().nodes()[0];
    assert!(node.provider_resources().scratch().is_none());
    assert!(node.provider_resources().binding().is_none());
    assert!(node.provider_resources().persistent().is_none());
    let resources = no_static(runtime.clone(), plan);
    let mut executor = PreparedTensorExecutor::new(
        executable.clone(),
        registry.bind_plan(executable).unwrap(),
        resources.clone(),
        host.clone(),
        TensorExecutorConfig::default(),
    )
    .unwrap();
    let seed = state_input(&host, SEED);
    let mut first: Option<ManagedHostBytes> = None;
    for ordinal in 0..2 {
        let outputs = executor
            .execute(
                id(format!("run.cuda.philox.{label}.{ordinal}")),
                id(format!("request.cuda.philox.{label}.{ordinal}")),
                vec![seed.clone()],
            )
            .unwrap();
        assert_eq!(outputs.len(), 1);
        assert_eq!(outputs[0].value_id().as_str(), NormalNoiseFamily::OUTPUT_ID);
        assert_eq!(outputs[0].tensor(), &output_spec);
        assert!(host.owns(outputs[0].bytes()));
        finite(outputs[0].bytes().bytes());
        assert_eq!(
            seed.bytes().bytes(),
            PhiloxSeedOffset::fresh(SEED).little_endian_bytes()
        );
        if let Some(previous) = &first {
            assert_eq!(
                outputs[0].bytes().bytes(),
                previous.bytes(),
                "same seed and shape changed bytes"
            );
            assert_eq!(
                host.usage().unwrap().allocated_bytes(),
                2 * output_bytes + 16
            );
        } else {
            first = Some(outputs[0].bytes().clone());
        }
        drop(outputs);
        assert_eq!(host.usage().unwrap().allocated_bytes(), output_bytes + 16);
    }
    drop(seed);
    let baseline = first.unwrap();
    let changed = executor
        .execute(
            id(format!("run.cuda.philox.{label}.changed")),
            id(format!("request.cuda.philox.{label}.changed")),
            vec![state_input(&host, OTHER_SEED)],
        )
        .unwrap();
    assert_eq!(changed.len(), 1);
    finite(changed[0].bytes().bytes());
    assert_ne!(
        changed[0].bytes().bytes(),
        baseline.bytes(),
        "changing only the seed high word had no effect"
    );
    drop(changed);
    managed_layout_check(&host, geometry.shape(), &baseline);
    assert_eq!(host.usage().unwrap().allocated_bytes(), output_bytes);
    let launch = CudaPhiloxDeviceGeometry::query(runtime)
        .unwrap()
        .launch(geometry.element_count())
        .unwrap();
    eprintln!("Philox {label}: shape={:?}, blocks={}, rounds={}, offset_advance={}, sha256={:x}; no Torch oracle",geometry.shape(),launch.blocks(),launch.rounds(),launch.offset_advance(),Sha256::digest(baseline.bytes()));
    drop((executor, compiled));
    close_resources(resources);
    assert_eq!(host.usage().unwrap().committed_bytes(), output_bytes);
    (host, baseline)
}

#[test]
#[ignore = "requires exclusive CUDA; actual explicit-state cuRAND kernel; no Torch oracle"]
fn managed_cuda_philox_fresh_seed_repeat_tail_layout_and_retirement() {
    let runtime = Arc::new(
        CudaDeviceRuntime::new_tensor_eager(CudaTensorRuntimeConfig {
            device: cuda_tensor_runtime_config(0, id("device.cuda.0")).unwrap(),
            usable_memory_bytes: USABLE_BYTES,
            bootstrap_memory_bytes: 1 << 30,
            stream_memory_bytes: 64 << 20,
            maximum_streams: 1,
            maximum_in_flight_per_stream: 1,
            maximum_commands_per_submission: 8,
            opaque_memory_profile: "experimental-unqualified-philox-test-v1".into(),
        })
        .unwrap(),
    );
    let geometry = CudaPhiloxDeviceGeometry::query(&runtime).unwrap();
    let registry = OperationRuntimeRegistry::new(
        vec![Box::new(philox_normal_bf16_contract().unwrap())],
        vec![cuda_vnext_philox_normal_bf16_provider(&runtime).unwrap()],
    )
    .unwrap();
    assert!(cuda_vnext_philox_normal_bf16_provider(&runtime).is_err());
    let descriptor = runtime.descriptor();
    let engine = EngineProviderDescriptor::new(
        id("provider.engine.cuda.tensor.philox"),
        ContractVersion::new(1, 0),
        descriptor.runtime_implementation_fingerprint.clone(),
        descriptor.id.clone(),
        descriptor.capabilities.clone(),
    )
    .unwrap();
    let catalog = registry
        .capability_catalog(descriptor.clone(), vec![engine])
        .unwrap();

    let block_capacity = u64::from(geometry.multiprocessors())
        * u64::from(geometry.max_threads_per_multiprocessor() / 256);
    let small = NormalNoiseConfig::new(3, 1, 257).unwrap();
    let small_launch = geometry.launch(771).unwrap();
    assert_eq!(u64::from(small_launch.blocks()), 4_u64.min(block_capacity));
    let (small_host, small_output) =
        exercise_shape(&runtime, &registry, &catalog, small, "block_tail");
    drop(small_output);
    assert_eq!(small_host.usage().unwrap().allocated_bytes(), 0);

    // Derive the boundary from actual device geometry. This deliberately
    // reaches all four normal4 components and a second round plus tail; it is
    // not tied to a GPU name, fixed SM count, or architecture-specific gate.
    let first_round = block_capacity.checked_mul(256 * 4).unwrap();
    let width = first_round / 9 + 1;
    let large = NormalNoiseConfig::new(3, 3, width).unwrap();
    let elements = width * 9;
    let launch = geometry.launch(elements).unwrap();
    assert_eq!(u64::from(launch.blocks()), block_capacity);
    assert_eq!(launch.rounds(), 2);
    assert!(elements > first_round && elements - first_round <= 9);
    let (host, output) = exercise_shape(&runtime, &registry, &catalog, large, "normal4_round_tail");
    drop((catalog, registry));
    // Previously retained provider/lane reservations must now be reusable.
    drop(cuda_vnext_philox_normal_bf16_provider(&runtime).unwrap());
    drop(runtime.create_stream().unwrap());
    drop(runtime);
    finite(output.bytes());
    let bytes = output.len();
    let alias = output.slice(bytes - 2..bytes).unwrap();
    let expected = [output.bytes()[bytes - 2], output.bytes()[bytes - 1]];
    drop(output);
    assert_eq!(alias.bytes(), expected);
    assert_eq!(host.usage().unwrap().allocated_bytes(), bytes);
    drop(alias);
    assert_eq!(host.usage().unwrap().committed_bytes(), 0);
    assert_eq!(host.usage().unwrap().allocated_bytes(), 0);
}
